architecture.h4_f:
msg = CBOR{v:1, teks, reply_to, sent_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST /api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, teks, reply_to?, thread_id?, mentions?, sent_at}
ct = AES-GCM-256-Encrypt(kunci_kamar, nonce, pt, aad=hex(id_kamar))
kawat = CBOR{
  v: 1,
  ciphertext: hex(ct), // dawa variabel
  nonce: hex(12B),
  pangirim_pseudo: hex(16 B),
  dikirim_ing: unix_ms
}

cryptoWire.h5_f:
njaba = CBOR{
  sumber_node: hex32,
  target_user: int64,
  inner_ciphertext: byte,
  batin_nonce: byte,
  dikirim_ing: unix_ms
}
sig = Ed25519-Sign(source_priv, njaba)
POST /federasi/kirim { amplop: njaba, sig: hex64 }

auth.h1_f:
POST /api/authentication/register
  { jeneng pangguna, sandhi, x25519_public_key, display_name, telpon?, email?, avatar_emoji }

Tanggapan 201 Digawe:
  { access_token, refresh_token, user_id, username, ... }

auth.h3_f:
access_token payload:
  { sub: user_id, jti: device_id, type: "access", exp: now + 15min }
muatan refresh_token:
  { sub: user_id, jti: device_id, typ: "refresh", exp: now + 30d }

HS256-ditandatangani kanthi rahasia 64-byte simpul saka .env

auth.h4_f:
register_begin(): tantangan = rand(32)
                    opsi = {rp.id, user.id, pubKeyCredParams, tantangan}
                    pilihan bali

register_finish(atestasi):
  verifikasi atestasi marang TPM / Secure Enclave root CA
  nyimpen { credential_id, public_key, counter: 0 }

auth.h7_f:
POST /api/authentication/qr/begin
  → { nonce: 128-bit hex, ttl: 60 }
QR payload = {nonce, user_id, server: "https://node.example" }

POST /api/authentication/qr/verifikasi { durung }
  → piranti anyar kadhaptar; JWTs bali.

rooms.h6_f:
sender_pseudo = HMAC-SHA256(room_pseudo_salt, sender_id)[:16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Rangka kipas: { tipe: "m", kamar, msg:{id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {jeneng file, ukuran, chunk_size_hint}
            ← {upload_id, chunk_size}
potongan PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
finalize POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {file_id, url}
TTL durung rampung: 24 jam

files.h4_f:
deny_list = {
  "aplikasi/x-dosexec",
  "aplikasi/x-sharedlib",
  "aplikasi/x-mach-biner",
}
yen magic.from_buffer(buf[:1024]) ing deny_list: bali 415

presence.h1_f:
klien: ing keystroke pisanan → send {type:"t", state:"start"}
         ora luwih ngirim kanggo 3 s kajaba owah-owahan negara
         10 s sawise keystroke pungkasan → send {type:"t", state:"stop"}
panrima: otomatis mandeg 10 s sawise pungkasan "wiwitan" yen ora "mandeg" teka

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS siaran {jinis:"c", jenis:"undang", id_telpon}
WS siaran {jinis:"c", jinis:"tawaran", sdp}
WS siaran {jinis:"c", jinis:"jawaban", sdp}
WS siaran {jinis:"c", jinis:"calon",es} × N
POST /api/calls/{call_id}/end

federation.h2_f:
amplop = {
  sumber_node: hex32,
  target_user: int64,
  inner_ciphertext: byte,
  batin_nonce : byte,
  dikirim_ing: unix_ms,
}
sig = Ed25519Sign(source_priv, CBOR(amplop))
POST /federasi/kirim { amplop, sig }

gossip.h3_f:
iklan = {pubkey, endpoint, advertised_at}
sig = Ed25519-Sign(pubkey_priv, CBOR(iklan))
muatan gosip: [..., {ad, sig}, ...]

panrima: verifikasi sig marang ad.pubkey → nyimpen yen ok
tambahan: PoW saka 2^18 nol anjog ing {pubkey, endpoint}

stealth.h2_f:
ClientHello byte = chrome_120_template karo {
  acak = acak kita,
  server_name = jeneng host kita (utawa ECH-dibungkus),
  session_id = id sesi kita,
}
JA4 = t13d_xxxx_xxxx_xxxx (cocog karo Chrome stabil saiki)

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {jeneng: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domain(t) = base32( SHA256(wiji ∥ YYYY-MM-DD) )[:16] + ".conto"

push.h4_f:
iOS NSE: didReceive(request) { decrypt(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { decrypt(remoteMessage.data) }
Web SW: self.addEventListener('push', e => decrypt(e.data))

controller.h2_f:
alat = tandha_alat
input = wit sumber, keys/release.key
nyata = {
  versi: "0.1.0",
  dibangun ing: unix_ms,
  file: [{path, sha256, size}, ...]
}
sig = Ed25519-Sign(release_priv, CBOR(manifest))
output = INTEGRITY.sig.json = {wujud, ditandatangani_dening: pub_hex, sig: sig_hex}

bots.h1_f:
gawe: POST /api/bots {username, display_name, code}
          → {bot_id, token, pubkey}
run: in-process (coroutine inside node)
      OR eksternal (long-poll /api/bots/{id}/updates, token-auth'd)
pesen: {teks, teken: Ed25519-Sign(bot_priv, canonical_msg)}

